sp_widget.client_script:
api.controller=function($scope, $window, $rootScope) { 
    var c = this;

    // Função para navegação. Reutilizável.
    c.navigateTo = function(pageId) {
        if (pageId) {
            $window.location.href = '?id=' + pageId;
        }
    };

    // NOVO: Função para trocar a URL da imagem no Client
    function updateImageContrast(enabled) {
        var card1 = c.data && c.data.card1;
        var card2 = c.data && c.data.card2;

        // Verifica se os dados essenciais estão presentes
        if (!card1 || !card2 || !card1.image_url_contrast || !card2.image_url_contrast) {
             // Retorna se o Server Script falhou em carregar as URLs de contraste
             return;
        }

        // Garante que a URL normal (base) seja salva para retornar
        if (!card1.image_url_normal) {
             card1.image_url_normal = card1.image_url;
             card2.image_url_normal = card2.image_url;
        }

        if (enabled) {
            // SE TRUE: Sobrescreve a URL ativa com a URL de Contraste
            card1.image_url = card1.image_url_contrast;
            card2.image_url = card2.image_url_contrast;

        } else {
            // SE FALSE: Sobrescreve a URL ativa com a URL Normal (salva)
            card1.image_url = card1.image_url_normal;
            card2.image_url = card2.image_url_normal;
        }

        // Força a digestão do Angular (essencial para listeners de $rootScope)
        if (!$scope.$$phase) {
            $scope.$apply(); 
        }
    }

    $scope.contrastIsActive = false;

    var contrastListener = $rootScope.$on('sp.contrast.toggled', function(event, data) {
        $scope.contrastIsActive = data.enabled; 
        updateImageContrast(data.enabled);
    });

    $scope.$on('$destroy', contrastListener);
}

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');


/* Variáveis de Cores (Reutilizadas) */
$main-bg: #f0f7ff; // Fundo azul claro suave
$header-title-color: #4773C6;  
$header-subtitle-color: #5d7fa2;  
$text-color: #4773C6;
$card-bg: #F1F4FB;
$card-border-color: #e0e0e0;
$card-title-color: #333;

$font-family-base: 'Roboto Flex', sans-serif;

/* NOVO: Largura máxima para centralização em telas grandes */
$content-max-width: 1200px; 

.tesouro-destaques-compact-container {
    /* AJUSTE: Fundo Branco para o widget */
    background-color: $card-bg; 
    padding: 20px 0; /* Padding vertical, o horizontal será tratado pelo wrapper */
    font-family: 'Poppins', sans-serif;
}

/* NOVO: Container para Centralização do Conteúdo */
.tesouro-content-wrapper {
    max-width: $content-max-width; /* Limita a largura do conteúdo */
    margin: 0 auto; /* Centraliza o wrapper na tela */
    padding: 0 20px; /* Adiciona padding horizontal para evitar que o conteúdo toque nas bordas em telas menores que $content-max-width */
}

/* Opcional: Remover padding/bg do painel se o widget fluid ocupar toda a tela */
.panel.dashboard-widget {
    background-color: transparent; // Deixa o fundo transparente para o container principal assumir o controle
    padding: 0; // Remove o padding padrão do container do ServiceNow
}

/* --- ESTILOS DO CABEÇALHO COMPACTO --- */
.destaques-header-compact {
    text-align: center;
    margin-bottom: 25px; 
    padding-bottom: 10px;

    .header-title {
        font-family: "Roboto Flex", sans-serif;
        font-size: 2.4rem; 
        font-weight: 700;
        color: $header-title-color;
        margin-bottom: 3px;
    }

    .header-subtitle {
        font-size: 15px; 
        font-weight: 400;
        color: $header-subtitle-color;
        margin: 0;
    }
}

/* --- ESTILOS DOS CARDS COMPACTOS --- */
.destaques-cards-row {
    display: flex; /* Mantido por compatibilidade, mas o d-flex no HTML é o principal */
    flex-wrap: wrap;   
    margin: 0 -10px; /* Mantém o gutter entre as colunas */
}

.destaque-card-compact {
    background-color: #fff;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);

    padding: 15px; 
    height: calc(100% - 20px); /* Ajuste: Mantém o card com altura total da coluna */

    margin: 10px;  
    display: flex;
    flex-direction: column;

    text-align: left;  

    cursor: pointer;
    transition: all 0.3s ease;

    &:hover {
        box-shadow: 0 6px 20px rgba(0, 0, 0, 0.2);
        transform: translateY(-3px);
    }

    .card-title-compact {
        font-family: $font-family-base;
        text-align: left;
        font-size: 1.8rem; 
        font-weight: 600;
        color: $text-color;
        padding: 0; 
        margin: 0 0 10px 0; /* Adicionado margem abaixo do título */
    }

    .card-content-compact {
        display: flex;
        flex-direction: column;

        /* O conteúdo (imagem) do card centralizado */
        align-items: center;  

        justify-content: flex-start;  
        flex-grow: 1;  
        padding-top: 5px; 
    }

    .card-image-content-compact {
        /* AJUSTE: Permite que a imagem cresça um pouco mais, mas mantendo-a responsiva */
        max-width: 85%; /* Ajuste a porcentagem conforme o tamanho ideal da sua imagem */
        height: auto;
        display: block;
        margin: 0 auto;
    }

    .card-subtitle-compact {
        font-size: 12px; 
        color: #555;
        margin-top: 10px;
        line-height: 1.3;
        text-transform: uppercase;
        font-weight: 500;
    }
}

/* --- Responsividade --- */
@media (max-width: 767px) {
    .tesouro-content-wrapper {
        padding: 0 15px; /* Ajuste de padding menor para mobile */
    }
    .destaque-card-compact .card-title-compact {
        text-align: left;
    }
}

/* ---------------------------------------------------------------------- */
/* --- ESTILOS DE ALTO CONTRASTE (Manter) --- */
/* ---------------------------------------------------------------------- */
.tesouro-destaques-compact-container.contrast-mode {

    background-color: #101010 !important;  

    .destaques-header-compact {
        .header-title {
            color: #fff;  
        }
        .header-subtitle {
            color: #ccc;  
        }
    }

    .destaque-card-compact {
        background-color: #000;  

        border: 0.1rem solid #777;  
        box-shadow: none;

        &:hover {
            background-color: #1a1a1a;  
            box-shadow: none;
            border-color: #fff;  
        }

        .card-title-compact {
            color: #fff;  
        }

        .card-subtitle-compact {
            color: #ccc;  
        }
    }
}

//mudança 19/10 abaixo

/* --- ADICIONE ESTE BLOCO NO FINAL DO SEU SASS/CSS --- */

/* Usamos um media query para garantir que esta regra só se aplique em telas desktop, 
   quando as colunas col-md-3 estiverem ativas (>= 992px) */
@media (min-width: 992px) {
    .destaques-cards-row {
        /* Define a linha como um container flexível */
        display: flex; 

        /* Centraliza o conteúdo horizontalmente (se o espaço permitir) */
        justify-content: center;

        /* Opcional: Garante que o alinhamento da linha não se quebre */
        width: 100%; 
    }
}

sp_widget.script:
(function() {
    /* populate the 'data' object */

    data.link = '404_sefaz';

    // URLs base
    var capagNormal = 'x_sded9_portal_t_0.capagAFase2.png';
    var rankingNormal = 'x_sded9_portal_t_0.rankingCLPfase2.png';

    // URLs de Contraste
    var capagContrast = 'capagPrintFase2.png';
    var rankingContrast = 'x_sded9_portal_t_0.rankingContrastefase2.png';

    // Dados do Cabeçalho
    data.header = {
        title: 'Destaques do Tesouro Estadual',
        subtitle: 'Liderança em gestão, progresso sentido por todos'
    };

    // Card 1
    data.card1 = {
        title: 'Resultados CAPAG',
        image_url: capagNormal,          // URL INICIAL
        image_url_contrast: capagContrast, // URL DE CONTRASTE
        description: 'Máxima saúde fiscal'
    };

    // Card 2
    data.card2 = {
        title: 'RANKING CLP',
        image_url: rankingNormal,          // URL INICIAL
        image_url_contrast: rankingContrast, // URL DE CONTRASTE
    };

})();
